239	    /**
240	     * The leading alphabetic REGION segment of a {@code memberId} formatted
241	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code 'NSW'} for {@code 'NSW271A2B3C4D5'}), or
242	     * {@code null} when {@code memberId} is {@code null} or does not begin with a letter. REGION is
243	     * always a run of letters immediately followed by the 2-digit fiscal year, so the leading letter
244	     * run is exactly the region code.
245	     */
246	    public static String regionSegment(String memberId) {
247	        if (memberId == null) {
248	            return null;
249	        }
250	        int i = 0;
251	        while (i < memberId.length() && Character.isLetter(memberId.charAt(i))) {
252	            i++;
253	        }
254	        return i == 0 ? null : memberId.substring(0, i);
255	    }
