257	    /**
258	     * The 2-digit fiscal-year (FY) segment of a {@code memberId} formatted
259	     * {@code '<REGION><FY><HASH8><CHK>'} (e.g. {@code '27'} for {@code 'NSW271A2B3C4D5'}), the two
260	     * digits immediately following the {@link #regionSegment(String) REGION}. Returns {@code null}
261	     * when {@code memberId} has no region prefix or is too short to carry a 2-digit FY.
262	     */
263	    public static String fiscalYearSegment(String memberId) {
264	        String region = regionSegment(memberId);
265	        if (region == null || memberId.length() < region.length() + 2) {
266	            return null;
267	        }
268	        String fy = memberId.substring(region.length(), region.length() + 2);
269	        for (int i = 0; i < fy.length(); i++) {
270	            if (fy.charAt(i) < '0' || fy.charAt(i) > '9') {
271	                return null;
272	            }
273	        }
274	        return fy;
275	    }
