293	    /**
294	     * Derive the owner's {@code membershipPoints}: a score starting at 0 that adds 2 when an email
295	     * is present, adds 1 when the owner's name was unique at creation time ({@code namesakeCount}
296	     * is 0), adds 2 when the owner belongs to a household of three or more members, and adds 3 when
297	     * the owner's tenure is at least one elapsed fiscal year (measured from the
298	     * {@code registrationDate} to today, where the fiscal year starts on 1 July).
299	     */
300	    @Transient
301	    public Integer getMembershipPoints() {
302	        int points = 0;
303	        if (this.email != null && !this.email.isBlank()) {
304	            points += 2;
305	        }
306	        if (Integer.valueOf(0).equals(this.namesakeCount)) {
307	            points += 1;
308	        }
309	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
310	            points += 2;
311	        }
312	        if (hasTenureOverOneFiscalYear()) {
313	            points += 3;
314	        }
315	        return points;
316	    }
