318	    /**
319	     * Derive the owner's numeric {@code membershipLevel}, from 1 to 4, by mapping the owner's
320	     * {@code membershipPoints}: level 1 for 0-1 points, level 2 for 2-3 points, level 3 for 4-5
321	     * points, and level 4 for 6 or more points. The result is then capped at the owner's
322	     * {@code membershipLevelCap} when one has been assigned, so a new household member can never
323	     * exceed one above the highest level already present in their household (see
324	     * {@link #getMembershipLevelCap()}).
325	     */
326	    @Transient
327	    public Integer getMembershipLevel() {
328	        int points = getMembershipPoints();
329	        int level;
330	        if (points <= 1) {
331	            level = 1;
332	        }
333	        else if (points <= 3) {
334	            level = 2;
335	        }
336	        else if (points <= 5) {
337	            level = 3;
338	        }
339	        else {
340	            level = 4;
341	        }
342	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
343	            return this.membershipLevelCap;
344	        }
345	        return level;
346	    }
