362	    /**
363	     * Whether the owner's tenure, measured as the number of elapsed fiscal years from
364	     * {@code registrationDate} to today (the fiscal year starting on 1 July), is at least one —
365	     * worth 3 membership points. A missing {@code registrationDate} (and therefore zero tenure)
366	     * never qualifies.
367	     */
368	    @Transient
369	    private boolean hasTenureOverOneFiscalYear() {
370	        if (this.registrationDate == null) {
371	            return false;
372	        }
373	        return fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1;
374	    }
