376	    /**
377	     * Derive the owner's read-only {@code fiscalYear}: {@code 'FY<YY>'} where YY is the last two
378	     * digits of the fiscal year of the owner's business-day-adjusted {@code registrationDate} (the
379	     * fiscal year starting on 1 July, so a registration on or after 1 July belongs to the fiscal year
380	     * ending the following 30 June). This is the same fiscal year the FY segment of the owner's
381	     * version-2 {@code memberId} is built from, so the two stay in lock-step. Falls back to the FY
382	     * segment carried by the {@code memberId} when the owner has no {@code registrationDate}, and
383	     * returns {@code null} when the owner has neither, so the field is omitted from the response.
384	     */
385	    @Transient
386	    public String getFiscalYear() {
387	        if (this.registrationDate != null) {
388	            return String.format("FY%02d", fiscalYearOf(this.registrationDate) % 100);
389	        }
390	        String fy = fiscalYearSegment(this.memberId);
391	        return fy == null ? null : "FY" + fy;
392	    }
