394	    /**
395	     * The fiscal year a {@code date} falls in, identified by its ending calendar year. The fiscal
396	     * year starts on 1 July, so dates on or after 1 July belong to the following year's fiscal year
397	     * (e.g. 1 July 2026 is fiscal year 2027), while dates from 1 January to 30 June belong to the
398	     * current year's fiscal year.
399	     */
400	    public static int fiscalYearOf(LocalDate date) {
401	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
402	    }
