404	    /**
405	     * The fixed version tag mixed into every version-2 owner identifier. Prefixing the hash inputs,
406	     * and the member id's embedded region code, with this tag guarantees every version-2 value
407	     * differs from the value the same owner would have produced under version 1, so no version-1
408	     * identifier is ever reproduced.
409	     */
410	    public static final String IDENTITY_VERSION_TAG = "V2";
411	
412	    /**
413	     * Derive the owner's version-2 {@code identityKey}, the single value used to detect duplicate
414	     * owners: the full lower-case hex SHA-256 of {@code 'V2' + '|' + normalizedTelephone + '|' +
415	     * lowerEmail + '|' + soundex(lastName)}. The fixed {@link #IDENTITY_VERSION_TAG 'V2'} tag is
416	     * mixed in so this version-2 key never coincides with the version-1 key. The telephone and email
417	     * are already stored in their canonical (E.164 / lower-cased) form, so a {@code null} or blank
418	     * email contributes an empty segment, and the last name is reduced to its {@link Soundex} code
419	     * (empty when there is no last name). Two owners are duplicates only when their whole
420	     * {@code identityKey} is equal.
421	     */
422	    @Transient
423	    public String getIdentityKey() {
424	        String telephonePart = this.telephone == null ? "" : this.telephone;
425	        String emailPart = (this.email == null || this.email.isBlank()) ? "" : this.email;
426	        String soundexPart = Soundex.encode(getLastName());
427	        return Sha256.hex(IDENTITY_VERSION_TAG + "|" + telephonePart + "|" + emailPart + "|" + soundexPart);
428	    }
