430	    /**
431	     * Derive the owner's read-only {@code locality}: the plain region code resolved from the owner's
432	     * postcode range first ({@code NSW 2000-2099, VIC 3000-3099, QLD 4000-4099}), then the canonical
433	     * region of the owner's city ({@code Sydney->NSW, Melbourne->VIC, Brisbane->QLD}), else
434	     * {@code 'UNKNOWN'}. The locality is <em>not</em> an identifier, so it is always the plain region
435	     * code and never carries the version-2 {@link #IDENTITY_VERSION_TAG 'V2'} tag embedded inside the
436	     * owner's {@code memberId}.
437	     */
438	    @Transient
439	    public String getLocality() {
440	        return PostcodeRules.resolveRegion(this.postcode, this.city);
441	    }
442	
443	    /**
444	     * Derive the owner's read-only {@code ownerSegment}, formatted {@code '<TIER>_<AREA>'}. TIER is
445	     * {@code PREMIUM} when the owner's {@code membershipLevel} is 3 or more, otherwise
446	     * {@code STANDARD}. AREA is {@code METRO} when the owner's {@link #getLocality() locality} is a
447	     * known region, otherwise {@code REGIONAL}. The region used here is the plain locality, so the
448	     * version-2 {@code 'V2'} tag embedded inside the owner's identifiers never leaks into the owner
449	     * segment.
450	     */
451	    @Transient
452	    public String getOwnerSegment() {
453	        String tier = getMembershipLevel() >= 3 ? "PREMIUM" : "STANDARD";
454	        String area = "UNKNOWN".equals(getLocality()) ? "REGIONAL" : "METRO";
455	        return tier + "_" + area;
456	    }
