273	    @Override
274	    @Transactional
275	    public void saveOwner(Owner owner) throws DataAccessException {
276	        boolean isNew = owner.isNew();
277	        // Resolve the effective registration date (supplied, or defaulted to the server date) and
278	        // roll it forward to the next business day so it never lands on a weekend. Everything
279	        // derived from the registration date below must use this adjusted value.
280	        LocalDate registrationDate = toBusinessDay(
281	            owner.getRegistrationDate() != null ? owner.getRegistrationDate() : LocalDate.now());
282	        owner.setRegistrationDate(registrationDate);
283	        if (owner.isNew()) {
284	            // The householdId is deterministic: the first 12 hex characters of SHA-256 over
285	            // (normalizedLastName | postcode), so owners with the same last name and postcode share
286	            // it automatically. It no longer feeds the identityKey, but is still reported and drives
287	            // the household member count and level cap below.
288	            owner.setHouseholdId(computeHouseholdId(owner));
289	            // The household is keyed on (last name, postcode), so the members are the existing owners
290	            // sharing both with this owner.
291	            List<Owner> householdMembers = findHouseholdMembers(owner);
292	            // Size of the household after this create: the existing members plus this new owner.
293	            owner.setHouseholdMemberCount(householdMembers.size() + 1);
294	            // A new owner joining an existing household has its derived membershipLevel capped at one
295	            // above the current maximum membershipLevel among its household members, so a new member
296	            // can never leap more than one level past the household. With no existing member no cap
297	            // applies.
298	            if (!householdMembers.isEmpty()) {
299	                int maxLevel = householdMembers.stream()
300	                    .mapToInt(Owner::getMembershipLevel)
301	                    .max()
302	                    .getAsInt();
303	                owner.setMembershipLevelCap(maxLevel + 1);
304	            }
305	        }
306	        // Single duplicate check: reject only when the new owner's WHOLE identityKey (the SHA-256 of
307	        // normalizedTelephone | email-or-empty | soundex(lastName)) equals an existing owner's. This
308	        // is the only 409; there is no separate household-duplicate rejection.
309	        if (owner.isNew() && isIdentityKeyAlreadyUsed(owner)) {
310	            throw new DuplicateIdentityException(owner.getIdentityKey());
311	        }
312	        // Soft-match: not a hard identityKey duplicate, but shares an existing owner's
313	        // soundex(lastName) and postcode. Still created, but flagged as a possible duplicate pointing
314	        // at the matching owner. Because the telephone is part of the identityKey, two owners with the
315	        // same last name and postcode but different telephones are flagged here rather than rejected.
316	        if (owner.isNew()) {
317	            Owner softMatch = findPossibleDuplicate(owner);
318	            if (softMatch != null) {
319	                owner.setPossibleDuplicate(true);
320	                owner.setPossibleDuplicateOf(softMatch.getId());
321	            }
322	        }
323	        if (owner.isNew()) {
324	            long ownersInCity = countOwnersInCity(owner);
325	            if (ownersInCity >= CityOwnerLimitExceededException.MAX_OWNERS_PER_CITY) {
326	                throw new CityOwnerLimitExceededException(owner.getCity());
327	            }
328	            // Between 40 and 49 existing owners (inclusive): created, but flagged as approaching the
329	            // per-city capacity limit of 50.
330	            owner.setCapacityWarning(ownersInCity >= CITY_CAPACITY_WARNING_THRESHOLD);
331	        }
332	        if (owner.isNew()
333	            && countOwnersRegisteredOn(registrationDate) >= DailyOwnerLimitExceededException.MAX_OWNERS_PER_DAY) {
334	            throw new DailyOwnerLimitExceededException(registrationDate);
335	        }
336	        if (owner.isNew() && owner.getMemberId() == null) {
337	            owner.setMemberId(generateMemberId(owner));
338	        }
339	        if (owner.isNew()) {
340	            owner.setNamesakeCount(countNamesakes(owner));
341	            owner.setBulkSignupWarning(
342	                countOwnersRegisteredOn(registrationDate) > BULK_SIGNUP_WARNING_THRESHOLD);
343	        }
344	        ownerRepository.save(owner);
345	        if (isNew) {
346	            AUDIT.info("owner created id={} memberId={} membershipLevel={} registrationDate={}",
347	                owner.getId(), owner.getMemberId(), owner.getMembershipLevel(),
348	                owner.getRegistrationDate());
349	            AUDIT.info(ownerCreatedEvent(owner));
350	            // Enqueue a welcome notification carrying the owner id and the memberId.
351	            NOTIFY.info("welcome owner id={} memberId={}", owner.getId(), owner.getMemberId());
352	        }
353	    }
