398	    /**
399	     * Report whether {@code owner}'s derived {@code identityKey} is already used by any existing
400	     * (non-deleted) owner. The key is the SHA-256 of telephone, email and {@code soundex(lastName)}
401	     * combined, so two owners collide only when their whole key is equal (see
402	     * {@link Owner#getIdentityKey()}).
403	     */
404	    private boolean isIdentityKeyAlreadyUsed(Owner owner) {
405	        String identityKey = owner.getIdentityKey();
406	        return ownerRepository.findAll().stream()
407	            .filter(existing -> !existing.isDeleted())
408	            .anyMatch(existing -> identityKey.equals(existing.getIdentityKey()));
409	    }
