411	    /**
412	     * Find an existing owner this (new) owner soft-matches against: one sharing the same
413	     * {@code soundex(lastName)} and postcode, but carrying a different {@code identityKey}. Returns
414	     * the lowest-id such owner, or {@code null} when the owner has no last name or postcode to match
415	     * on, or nothing matches. The caller only invokes this once the hard {@code identityKey}
416	     * duplicate check has already passed.
417	     */
418	    private Owner findPossibleDuplicate(Owner owner) {
419	        String key = soundexPostcodeKey(owner);
420	        if (key == null) {
421	            return null;
422	        }
423	        String identityKey = owner.getIdentityKey();
424	        return ownerRepository.findAll().stream()
425	            .filter(existing -> !existing.isDeleted())
426	            .filter(existing -> key.equals(soundexPostcodeKey(existing))
427	                && !identityKey.equals(existing.getIdentityKey()))
428	            .min(Comparator.comparing(Owner::getId))
429	            .orElse(null);
430	    }
