432	    /**
433	     * Build the soft-match key, {@code soundex(lastName) + '|' + postcode}: the basis on which a new
434	     * owner is flagged a possible duplicate of an existing owner. Returns {@code null} when the owner
435	     * has no last name to encode or no postcode to key on.
436	     */
437	    private String soundexPostcodeKey(Owner owner) {
438	        String soundex = Soundex.encode(owner.getLastName());
439	        String postcode = owner.getPostcode();
440	        if (soundex.isEmpty() || postcode == null || postcode.isBlank()) {
441	            return null;
442	        }
443	        return soundex + "|" + postcode;
444	    }
