448	     * name as {@code owner}, compared case-insensitively. Returns zero when the owner's name is
449	     * unique among the existing owners.
450	     */
451	    private int countNamesakes(Owner owner) {
452	        String firstName = owner.getFirstName();
453	        String lastName = owner.getLastName();
454	        if (firstName == null || lastName == null) {
455	            return 0;
456	        }
457	        return (int) ownerRepository.findAll().stream()
458	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
459	                && lastName.equalsIgnoreCase(existing.getLastName()))
460	            .count();
461	    }
