463	    /**
464	     * Find the owners that already belong to the same household as {@code owner}, i.e. share both its
465	     * last name and its postcode. Last names are compared case-insensitively with collapsed
466	     * whitespace; postcodes are compared exactly. This is the same keying used by
467	     * {@link #computeHouseholdId(Owner)}, so these are exactly the existing owners that carry the
468	     * owner's computed {@code householdId}. Returns an empty list when the owner has no last name or
469	     * postcode to match on.
470	     */
471	    private List<Owner> findHouseholdMembers(Owner owner) {
472	        String key = householdKey(owner);
473	        if (key == null) {
474	            return List.of();
475	        }
476	        return ownerRepository.findAll().stream()
477	            .filter(existing -> !existing.isDeleted())
478	            .filter(existing -> key.equals(householdKey(existing)))
479	            .toList();
480	    }
