482	    /**
483	     * Compute an owner's deterministic version-2 {@code householdId}: the first 12 lower-case hex
484	     * characters of SHA-256 over the UTF-8 bytes of {@code 'V2' + '|' + normalizedLastName + '|' +
485	     * postcode} (see {@link #householdKey(Owner)}), with the fixed {@link Owner#IDENTITY_VERSION_TAG
486	     * 'V2'} tag mixed in so the value never coincides with the version-1 householdId. Owners with the
487	     * same last name and postcode therefore share the same {@code householdId} automatically. Returns
488	     * {@code null} when the owner has no last name or postcode, so it does not belong to a shared
489	     * household.
490	     */
491	    private String computeHouseholdId(Owner owner) {
492	        String key = householdKey(owner);
493	        return key == null ? null
494	            : Sha256.hexPrefix(Owner.IDENTITY_VERSION_TAG + "|" + key, 6, false);
495	    }
496	
497	    /**
498	     * Build the owner's household key, {@code normalizedLastName + '|' + postcode}, the single value
499	     * that identifies a household. The last name is normalized case-insensitively with collapsed
500	     * whitespace (see {@link #normalizeHouseholdKey}) and the postcode is used exactly as stored.
501	     * Returns {@code null} when the owner has no last name or postcode to key on. This is the shared
502	     * basis for both {@link #computeHouseholdId(Owner)} and household membership matching, so the two
503	     * cannot drift apart.
504	     */
505	    private String householdKey(Owner owner) {
506	        String lastName = normalizeHouseholdKey(owner.getLastName());
507	        String postcode = owner.getPostcode();
508	        if (lastName == null || postcode == null || postcode.isBlank()) {
509	            return null;
510	        }
511	        return lastName + "|" + postcode;
512	    }
513	
514	    /**
515	     * Normalize a value for case-insensitive, whitespace-insensitive household comparison by
516	     * trimming, collapsing internal runs of whitespace to a single space and lower-casing it.
517	     */
518	    private String normalizeHouseholdKey(String value) {
519	        return value == null ? null : value.trim().replaceAll("\\s+", " ").toLowerCase();
520	    }
521	
522	    /**
523	     * Build an owner's unified version-2 {@code memberId} as {@code '<REGION><FY><HASH8><CHK>'}:
524	     * REGION the version-2 region code — the region resolved from the owner's postcode (falling back
525	     * to the owner's city, else {@code 'UNKNOWN'}) with the fixed {@link Owner#IDENTITY_VERSION_TAG
526	     * 'V2'} tag mixed in (e.g. {@code 'NSWV2'}); FY the two-digit fiscal year of the owner's
527	     * business-day-adjusted {@code registrationDate} (the fiscal year starting 1 July); HASH8 the
528	     * first 8 upper-case hex characters of SHA-256 computed over the {@code 'V2'} tag, the owner's
529	     * normalized telephone and the owner's last name; and CHK a single Luhn check digit computed over
530	     * the digits of {@code <REGION><FY><HASH8>} (e.g. {@code 'NSWV2271A2B3C4D5'}). The {@code 'V2'}
531	     * tag mixed into both the region and the hash guarantees the id never coincides with the owner's
532	     * version-1 memberId. The identity is fully derived from the owner's own attributes.
533	     * <p>
534	     * When the derived id collides with an existing owner's {@code memberId}, a {@code '-<n>'}
535	     * suffix is appended with the smallest {@code n} of 2 or more that makes it unique, so distinct
536	     * owners always receive distinct member ids.
537	     */
538	    private String generateMemberId(Owner owner) {
539	        // version-2 region code: the owner's plain region (its locality) with the fixed 'V2' tag
540	        // mixed in (e.g. 'NSWV2'), used only inside the identifier. The reported locality stays plain.
541	        String region = owner.getLocality() + Owner.IDENTITY_VERSION_TAG;
542	        String fy = String.format("%02d", Owner.fiscalYearOf(owner.getRegistrationDate()) % 100);
543	        String core = region + fy + memberHash(owner);
544	        return deduplicateMemberId(core + luhnCheckDigit(core));
545	    }
546	
547	    /**
548	     * Return {@code base} when no existing owner already uses it as their {@code memberId};
549	     * otherwise append {@code '-<n>'} with the smallest {@code n} of 2 or more that is not already
550	     * taken (counting both the bare {@code base} and any earlier {@code '-<n>'} de-duplications).
551	     */
552	    private String deduplicateMemberId(String base) {
553	        Set<String> existing = ownerRepository.findAll().stream()
554	            .map(Owner::getMemberId)
555	            .filter(Objects::nonNull)
556	            .collect(Collectors.toSet());
557	        if (!existing.contains(base)) {
558	            return base;
559	        }
560	        int n = 2;
561	        while (existing.contains(base + "-" + n)) {
562	            n++;
563	        }
564	        return base + "-" + n;
565	    }
566	
567	    /**
568	     * Compute the HASH8 segment of an owner's version-2 {@code memberId}: the first 8 upper-case hex
569	     * characters of SHA-256 over the UTF-8 bytes of the fixed {@link Owner#IDENTITY_VERSION_TAG 'V2'}
570	     * tag concatenated with the owner's normalized telephone and the owner's last name.
571	     */
572	    private String memberHash(Owner owner) {
573	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
574	        String lastName = owner.getLastName() == null ? "" : owner.getLastName();
575	        return Sha256.hexPrefix(Owner.IDENTITY_VERSION_TAG + telephone + lastName, 4, true);
576	    }
577	
578	    /**
579	     * Compute the single Luhn check digit (0-9) over the digits contained in {@code s}; non-digit
580	     * characters are ignored. This is the CHK segment appended to {@code <REGION><FY><HASH8>} to
581	     * form the owner's {@code memberId}.
582	     */
583	    private int luhnCheckDigit(String s) {
584	        int sum = 0;
585	        boolean dbl = true;
586	        for (int i = s.length() - 1; i >= 0; i--) {
587	            char c = s.charAt(i);
588	            if (c < '0' || c > '9') {
589	                continue;
590	            }
591	            int d = c - '0';
592	            if (dbl) {
593	                d *= 2;
594	                if (d > 9) {
595	                    d -= 9;
596	                }
597	            }
598	            sum += d;
599	            dbl = !dbl;
600	        }
601	        return (10 - (sum % 10)) % 10;
602	    }
603	
604	    /**
605	     * Count the owners that already exist (before this create) in the same city as {@code owner},
606	     * compared case-insensitively.
607	     */
608	    private long countOwnersInCity(Owner owner) {
609	        String city = owner.getCity();
610	        return ownerRepository.findAll().stream()
611	            .filter(existing -> city.equalsIgnoreCase(existing.getCity()))
612	            .count();
613	    }
614	
615	    /**
616	     * Count the owners that already exist (before this create) whose {@code registrationDate} falls
617	     * on the given {@code date}. Used to enforce the per-day create cap.
618	     */
619	    private long countOwnersRegisteredOn(LocalDate date) {
620	        return ownerRepository.findAll().stream()
621	            .filter(existing -> date.equals(existing.getRegistrationDate()))
622	            .count();
623	    }
624	
625	    /**
626	     * Fixed public holidays that registration dates must never fall on. Together with weekends these
627	     * are the non-business days skipped by {@link #toBusinessDay(LocalDate)}.
628	     */
629	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
630	        LocalDate.parse("2026-01-01"),
631	        LocalDate.parse("2026-01-26"),
632	        LocalDate.parse("2026-04-25"),
633	        LocalDate.parse("2026-12-25"),
634	        LocalDate.parse("2026-12-28"));
635	
636	    /**
637	     * Roll {@code date} forward to the next business day, skipping weekends (Saturday and Sunday) and
638	     * the fixed {@link #PUBLIC_HOLIDAYS public holidays}. A date already on a business day is returned
639	     * unchanged. Registration dates are required to fall on a business day.
640	     */
641	    private LocalDate toBusinessDay(LocalDate date) {
642	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY
643	            || date.getDayOfWeek() == DayOfWeek.SUNDAY
644	            || PUBLIC_HOLIDAYS.contains(date)) {
645	            date = date.plusDays(1);
646	        }
647	        return date;
648	    }
