44	/**
45	 * Global Exception handler for REST controllers.
46	 * <p>
47	 * This class handles exceptions thrown by REST controllers and returns appropriate HTTP responses to the client.
48	 *
49	 * @author Vitaliy Fedoriv
50	 * @author Alexander Dudkin
51	 */
52	@ControllerAdvice
53	public class ExceptionControllerAdvice {
54	
55	    private static final Logger logger = LoggerFactory.getLogger(ExceptionControllerAdvice.class);
56	    private static final String ERROR_UNEXPECTED = "An unexpected error occurred while processing your request";
57	    private static final String ERROR_DATA_INTEGRITY = "The requested resource could not be processed due to a data constraint violation";
58	    private static final String ERROR_INVALID_REQUEST = "The request contains invalid or missing parameters";
59	
60	    /**
61	     * Private method for constructing the {@link ProblemDetail} object passing the name and details of the exception
62	     * class.
63	     *
64	     * @param e     Object referring to the thrown exception.
65	     * @param status HTTP response status.
66	     * @param url URL request.
67	     */
68	    private ProblemDetail detailBuild(Exception e, HttpStatus status, StringBuffer url, String detail) {
69	        ProblemDetail problemDetail = ProblemDetail.forStatus(status);
70	        problemDetail.setType(URI.create(url.toString()));
71	        problemDetail.setTitle(e.getClass().getSimpleName());
72	        problemDetail.setDetail(detail);
73	        problemDetail.setProperty("timestamp", Instant.now());
74	        problemDetail.setProperty("schemaValidationErrors", List.<ValidationMessageDto>of());
75	        return problemDetail;
76	    }
77	
78	    /**
79	     * Re-throws {@link AccessDeniedException} so Spring Security's {@code ExceptionTranslationFilter}
80	     * translates it as it normally would - 403 for an authenticated user lacking the required role,
81	     * or the configured entry point for an anonymous one. Without this, {@link #handleGeneralException}
82	     * would catch it and report an authorization failure as a 500.
83	     *
84	     * @param e The {@link AccessDeniedException} to propagate
85	     * @throws AccessDeniedException always
86	     */
87	    @ExceptionHandler(AccessDeniedException.class)
88	    public void handleAccessDeniedException(AccessDeniedException e) throws AccessDeniedException {
89	        throw e;
90	    }
91	
92	    /**
93	     * Handles {@link DuplicateIdentityException}, raised by the service layer when a new owner's whole
94	     * derived {@code identityKey} (the SHA-256 of normalized telephone, email and soundex(lastName))
95	     * equals an existing owner's, by returning a 409 Conflict status. This single handler replaces the
96	     * former separate telephone, email and household duplicate handlers.
97	     *
98	     * @param e The {@link DuplicateIdentityException} to be handled
99	     * @param request {@link HttpServletRequest} object referring to the current request.
100	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
101	     */
102	    @ExceptionHandler(DuplicateIdentityException.class)
103	    @ResponseBody
104	    public ResponseEntity<ProblemDetail> handleDuplicateIdentityException(DuplicateIdentityException e, HttpServletRequest request) {
105	        logger.warn("Duplicate identity at {} {}: {}",
106	            request.getMethod(),
107	            request.getRequestURI(),
108	            e.getMessage());
109	        HttpStatus status = HttpStatus.CONFLICT;
110	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
111	        return ResponseEntity.status(status).body(detail);
112	    }
113	
114	    /**
115	     * Handles {@link CityOwnerLimitExceededException}, raised by the service layer when a new owner's
116	     * city already contains the maximum number of owners, by returning a 409 Conflict status.
117	     *
118	     * @param e The {@link CityOwnerLimitExceededException} to be handled
119	     * @param request {@link HttpServletRequest} object referring to the current request.
120	     * @return A {@link ResponseEntity} containing the error information and a 409 Conflict status
121	     */
122	    @ExceptionHandler(CityOwnerLimitExceededException.class)
123	    @ResponseBody
124	    public ResponseEntity<ProblemDetail> handleCityOwnerLimitExceededException(CityOwnerLimitExceededException e, HttpServletRequest request) {
125	        logger.warn("City owner limit exceeded at {} {}: {}",
126	            request.getMethod(),
127	            request.getRequestURI(),
128	            e.getMessage());
129	        HttpStatus status = HttpStatus.CONFLICT;
130	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
131	        return ResponseEntity.status(status).body(detail);
132	    }
133	
134	    /**
135	     * Handles {@link DailyOwnerLimitExceededException}, raised by the service layer when the maximum
136	     * number of owners for the current day have already been registered, by returning a 429 Too Many
137	     * Requests status.
138	     *
139	     * @param e The {@link DailyOwnerLimitExceededException} to be handled
140	     * @param request {@link HttpServletRequest} object referring to the current request.
141	     * @return A {@link ResponseEntity} containing the error information and a 429 Too Many Requests status
142	     */
143	    @ExceptionHandler(DailyOwnerLimitExceededException.class)
144	    @ResponseBody
145	    public ResponseEntity<ProblemDetail> handleDailyOwnerLimitExceededException(DailyOwnerLimitExceededException e, HttpServletRequest request) {
146	        logger.warn("Daily owner limit exceeded at {} {}: {}",
147	            request.getMethod(),
148	            request.getRequestURI(),
149	            e.getMessage());
150	        HttpStatus status = HttpStatus.TOO_MANY_REQUESTS;
151	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), e.getMessage());
