154	
155	    /**
156	     * Handles all general exceptions by returning a 500 Internal Server Error status with error details.
157	     *
158	     * @param e The {@link Exception} to be handled
159	     * @param request {@link HttpServletRequest} object referring to the current request.
160	     * @return A {@link ResponseEntity} containing the error information and a 500 Internal Server Error status
161	     */
162	    @ExceptionHandler(Exception.class)
163	    @ResponseBody
164	    public ResponseEntity<ProblemDetail> handleGeneralException(Exception e, HttpServletRequest request) {
165	        logger.error("Unexpected error at {} {}", request.getMethod(), request.getRequestURI(), e);
166	        HttpStatus status = HttpStatus.INTERNAL_SERVER_ERROR;
167	        ProblemDetail detail = this.detailBuild(e, status, request.getRequestURL(), ERROR_UNEXPECTED);
168	        return ResponseEntity.status(status).body(detail);
169	    }
